  const h = M.escapeHtml;
  const badge = (text, tone = 'neutral') => `<span class="badge ${h(tone)}">${h(text)}</span>`;
  const button = (text, action, value = '', style = '') => `<button type="button" class="button ${h(style)}" data-action="${h(action)}" data-value="${h(value)}">${h(text)}</button>`;
  const disabled = (text, reason, style = '') => `<button type="button" class="button ${h(style)}" disabled title="${h(reason)}" aria-label="${h(text + ". " + reason)}">${h(text)}</button>`;
  const help = (label, text) => `<details class="help-tip"><summary aria-label="About ${h(label)}"><span aria-hidden="true">?</span></summary><span class="help-tip-content">${h(text)}</span></details>`;
  const row = (label, value, note = '', helpText = '', helpLabel = label) => `<div class="fact"><dt>${h(label)}${helpText ? help(helpLabel, helpText) : ''}</dt><dd>${h(value)}${note ? `<small>${h(note)}</small>` : ''}</dd></div>`;
  const sourceEvidenceHistorical = (s, x) => s.sourceHistorical || x.measurementHistorical;
