    const more = s.actionTarget !== 'diagnostics' ? button('Diagnostics', 'page', 'diagnostics', 'text-button') : '';
    return `${title('YOUR SYSTEM CLOCK', 'Clock status', '')}
    <section class="status-banner ${h(s.tone)}" aria-labelledby="state-title"><div class="status-top">${badge(profileBadgeLabel(state), s.id === 'ntp' ? 'warning' : 'neutral')}${s.historical ? badge('Historical evidence', 'warning') : badge('Sample snapshot', 'subtle')}${s.id === 'stale' ? badge('Last snapshot · ' + s.snapshot, 'warning') : ''}${s.future ? badge('Future recovery design', 'warning') : ''}</div><div class="status-content"><div><h2 id="state-title">${h(s.title)}</h2><p>${h(s.description)}</p><div class="next-action">${h(s.next)}</div>${effect}${qualifier}</div></div><div class="status-actions">${syncButton(state)}${s.actionTarget === 'service-settings' && state.serviceControl.observation !== 'running' ? '' : contextAction(s)}${more}</div>${syncFeedback(state)}</section>
    <section class="panel status-summary" aria-label="Time estimate and evidence"><dl class="status-summary-facts">${row(s.historical ? 'Last known offset' : prior ? 'Retained model offset' : 'Estimated offset', `${off.value}${off.unit ? ' ' + off.unit : ''}`, directionNote)}${row(s.historical ? 'Last known uncertainty' : prior ? 'Retained model uncertainty' : 'Estimated uncertainty', s.uncertainty === null ? '—' : '±' + s.uncertainty.toFixed(1) + ' ms', 'Model estimate, not a precision guarantee', 'Uncertainty is a model estimate of possible error, not a guarantee of accuracy or a probability.', 'estimated uncertainty')}${row('Authentication', s.authentication, '', 'NTS authenticates server responses, but it does not guarantee that a server clock is accurate. Plain NTP responses are unauthenticated.')}${row('Source agreement', `${s.agree} of ${s.total} identities · ${s.agreement}`, s.agreementNote || '', 'Eligible source identities must meet the configured minimum and a majority must agree. Authentication alone does not establish agreement.')}${row('Last qualified estimate', s.estimate)}</dl></section>`;
